/* 主容器样式 */
.container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

/* 头部样式 */
.header {
    background-color: #ffffff;
    border-bottom: 1px solid #eeeeee;
    padding: 15px 0;
}

.header .logo {
    font-size: 24px;
    font-weight: bold;
    color: #333333;
}

/* 导航样式 */
.nav {
    display: flex;
    gap: 20px;
}

.nav-link {
    color: #666666;
    text-decoration: none;
    padding: 10px 15px;
    border-radius: 4px;
    transition: all 0.3s ease;
}

.nav-link:hover {
    background-color: #f5f5f5;
    color: #000000;
}

.nav-link.active {
    background-color: #007bff;
    color: #ffffff;
}

/* 按钮样式 */
.btn {
    display: inline-block;
    padding: 10px 20px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 14px;
    transition: all 0.2s ease;
}

.btn-primary {
    background-color: #007bff;
    color: #ffffff;
}

.btn-primary:hover {
    background-color: #0056b3;
}

/* 响应式 */
@media (max-width: 768px) {
    .container {
        padding: 10px;
    }

    .nav {
        flex-direction: column;
        gap: 10px;
    }
}

