// 示例 JavaScript 代码
class Calculator {
    constructor(initialValue = 0) {
        this.value = initialValue;
        this.history = [];
    }

    add(number) {
        this.history.push({ operation: 'add', value: number });
        this.value += number;
        return this;
    }

    subtract(number) {
        this.history.push({ operation: 'subtract', value: number });
        this.value -= number;
        return this;
    }

    multiply(number) {
        this.history.push({ operation: 'multiply', value: number });
        this.value *= number;
        return this;
    }

    divide(number) {
        if (number === 0) {
            throw new Error('Cannot divide by zero');
        }
        this.history.push({ operation: 'divide', value: number });
        this.value /= number;
        return this;
    }

    reset() {
        this.value = 0;
        this.history = [];
        return this;
    }

    getHistory() {
        return this.history;
    }

    getValue() {
        return this.value;
    }
}

// 使用示例
function main() {
    const calc = new Calculator(10);

    calc.add(5)
        .multiply(2)
        .subtract(3)
        .divide(2);

    console.log('当前值:', calc.getValue());
    console.log('操作历史:', calc.getHistory());

    // 调试代码
    debugger;

    return calc.getValue();
}

// 工具函数
const utils = {
    formatNumber: (num) => {
        return num.toLocaleString('zh-CN');
    },

    isValidNumber: (value) => {
        return typeof value === 'number' && !isNaN(value) && isFinite(value);
    },

    clamp: (value, min, max) => {
        return Math.min(Math.max(value, min), max);
    }
};

// 立即执行函数
(function() {
    const result = main();
    console.log('最终结果:', utils.formatNumber(result));
})();

